use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Gen {
    kind: string,
    a: int,
    b: int,
    h: int,
}

impl Shape for Gen {
    fn name(self) -> string {
        self.kind
    }
    fn corners(self) -> int {
        if self.kind == "rtri" { 3 } else { 4 }
    }
    fn double_area(self) -> int {
        if self.kind == "square" {
            2 * self.a * self.a
        } else if self.kind == "rect" {
            2 * self.a * self.b
        } else if self.kind == "rtri" {
            self.a * self.b
        } else {
            (self.a + self.b) * self.h
        }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total = 0
    let mut best = -1
    let mut best_name = "none"
    for line in text.lines() {
        let parts = line.split_whitespace().map(|x| x.to_string()).collect::<Vec<string>>()
        if parts.len() == 0 { continue }
        let mut nums: Vec<int> = []
        let mut i = 1
        while i < parts.len() {
            nums.push(parts[i].parse::<int>().unwrap_or(0))
            i += 1
        }
        let mut s = Gen { kind: parts[0], a: nums[0], b: 0, h: 0 }
        if nums.len() > 1 { s.b = nums[1] }
        if nums.len() > 2 { s.h = nums[2] }
        let d = s.double_area()
        println("${s.name()} corners=${s.corners()} area2=${d}")
        total += d
        if d > best {
            best = d
            best_name = s.name()
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

